#include "stdafx.h"#include "SCB.h"KSCB::KSCB(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Scale Factor",  "Bias"};BOOL KSCB::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    m_CurParameterID = -1;    CStringA s;    if( !m_ReadParams )      s.Format( "K = %s", szText.c_str() );    if( 1==m_ReadParams )      s.Format( "Bias = %s", szText.c_str() );    if( !s.IsEmpty() )      m_Settings.push_back( s.GetBuffer() );    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}